#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
"""Whole-system task map from a FISH task set (extract_fish_tasks.py JSON), rendered with graphviz:
  <prefix>_full.*       every data callback of the multi-callback tasks (+ the single-callback tasks linked to them), ALL edges:
                        solid = identity-paired trigger edges, dashed = links between tasks (polled reads / held pointers, bundled per
                        task pair with topic, count and age), dotted red = state / join candidates (no evidence) — the dense graph
  <prefix>_tasks.*      the same layout, tasks coloured = the breakdown FISH derives (each dashed / dotted edge is a cut)
  <prefix>_collapsed.*  one node per task (source, size), edges = the bundled links between tasks
usage: system_map.py <fish_tasks.json> -o <prefix> [--all-singles] [--no-candidates] [--png-dpi 110]"""
import argparse, collections, json, os, subprocess, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'postprocess'))
from task_viz import short_node, short_ent  # noqa: E402

FILLS = ['#cde2fb', '#fbdccf', '#c9efe0', '#fbe9b8', '#dcd7f7', '#f9dde8', '#d6f0f5', '#eee5c8', '#e0e8d2', '#f3d9c4', '#d9e6f2', '#f0d6e8', '#d8ead3', '#f5e6cc', '#e4dcf5', '#d0ebe4', '#f2dcd4', '#dde6ee', '#ebe3d5', '#d5e8f7']
STROKES = ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#6250d6', '#e87ba4', '#1a8fa3', '#9a7b1a', '#5a7a2a', '#c0652b', '#3a6ea5', '#a04a86', '#4d8a3a', '#b4862c', '#6f5fb3', '#2f8c7a', '#b05a46', '#4b6c86', '#8a7a4e', '#3b7cb8']


def esc(s):
    return str(s).replace('\\', '\\\\').replace('"', '\\"')


def main():
    ap = argparse.ArgumentParser(); ap.add_argument('json'); ap.add_argument('-o', '--out', required=True); ap.add_argument('--all-singles', action='store_true')
    ap.add_argument('--no-candidates', action='store_true'); ap.add_argument('--png-dpi', type=int, default=110)
    ap.add_argument('--no-fold', action='store_true', help='do not fold pure sink callbacks (no outgoing edge, no link between tasks) into one "+k subscribers" box per publisher'); a = ap.parse_args()
    d = json.load(open(a.json)); data = [t for t in d['tasks'] if not t.get('infra')]
    T = {t['id']: t for t in data}; VT = {v['id']: t['id'] for t in data for v in t['vertices']}; V = {v['id']: v for t in data for v in t['vertices']}
    multi = {t['id'] for t in data if t['size'] > 1}
    links = [s for s in d['sampled'] if s.get('method') not in ('tf_lookup', 'tf_static') and s['reader_vertex'] in VT]
    bund = collections.defaultdict(list)       # (writer task, reader task) -> [(topic, age, n)]
    for s in links:
        for wt in (s.get('writer_tasks') or []):
            if wt in T and wt != s['reader_task']: bund[(wt, s['reader_task'])].append((s['topic'] or s.get('method'), s.get('age_p50'), s.get('n')))
    cands = [] if a.no_candidates else [c for c in d['candidates'] if c['u'] in VT and c['v'] in VT and VT[c['u']] != VT[c['v']]]
    cbund = collections.defaultdict(int)
    for c in cands: cbund[(VT[c['u']], VT[c['v']])] += 1
    linked = {t for pair in list(bund) + list(cbund) for t in pair}
    shown = multi | ({t['id'] for t in data} if a.all_singles else {t for t in linked if any(p in multi for pair in list(bund) + list(cbund) if t in pair for p in pair)})
    tasks = [T[i] for i in sorted(shown, key=lambda i: -T[i]['size'])]
    # fold pure sinks: a callback with no outgoing trigger edge, not reading from / read by another task, not a candidate endpoint
    outdeg = collections.Counter(e['u'] for t in data for e in t['edges']); busy = set()
    for sm in links: busy.add(sm['reader_vertex'])
    for c in cands: busy.add(c['u']); busy.add(c['v'])
    pub_any = collections.defaultdict(set)
    for t in data:
        for e in t['edges']:
            if e.get('topic'): pub_any[(t['id'], e['topic'])].add(e['u'])
    for sm in links:
        for wt in (sm.get('writer_tasks') or []):
            for u in pub_any.get((wt, sm['topic']), ()): busy.add(u)
    fold = {}            # sink vertex -> (task, parent vertex) group
    if not a.no_fold:
        parents = collections.defaultdict(set)
        for t in tasks:
            for e in t['edges']: parents[e['v']].add(e['u'])
        groups = collections.defaultdict(list)
        for t in tasks:
            for v in t['vertices']:
                if outdeg[v['id']] == 0 and v['id'] not in busy and len(parents[v['id']]) == 1 and t['size'] > 1:
                    groups[(t['id'], next(iter(parents[v['id']])))].append(v['id'])
        for (tid, par), vs in groups.items():
            if len(vs) >= 2:
                for x in vs: fold[x] = (tid, par)
    folded_groups = collections.defaultdict(list)
    for x, g in fold.items(): folded_groups[g].append(x)
    color = {t['id']: i % len(FILLS) for i, t in enumerate(tasks)}
    src_label = lambda t: (t['sources'][0]['name'].split(' / ')[-1] if t['sources'] else '?')[:28]

    def node_label(v):
        node = (v.get('node') or '').rstrip('/').split('/')[-1][:26]; return esc(node) + '\\n' + esc(short_ent(v.get('etype'), v.get('entity'), None, 26))

    def write(kind):
        coloured = kind != 'full'
        L = ['digraph fish {', 'rankdir=LR; splines=true; nodesep=0.08; ranksep=0.45; outputorder=edgesfirst;',
             'node [shape=box, style="rounded,filled", fontname="Helvetica", fontsize=7, margin="0.04,0.02", penwidth=0.8, height=0.3];',
             'edge [fontname="Helvetica", fontsize=7, arrowsize=0.5, penwidth=0.8, color="#4b4a45"];',
             f'label="FISH task map — session {esc(d["session"])}: {len(tasks)} data tasks shown ({len(multi)} with >1 callback), solid = identity-paired trigger edges, dashed = polled reads / held pointers between tasks (bundled per task pair), dotted red = candidates (no evidence){"" if coloured else " — before the breakdown: one dense graph"}"; labelloc=t; fontname="Helvetica"; fontsize=12;']
        if kind == 'collapsed':
            for t in tasks:
                f, s = (FILLS[color[t['id']]], STROKES[color[t['id']]]); L.append(f'T{t["id"]} [label="task {t["id"]}\\n{esc(src_label(t))}\\n{t["size"]} callback(s)", fillcolor="{f}", color="{s}", fontsize=9];')
            for (wt, rt), lst in bund.items():
                if wt in shown and rt in shown:
                    top = collections.Counter(x[0] for x in lst).most_common(1)[0][0]; ages = [x[1] for x in lst if x[1]]
                    L.append(f'T{wt} -> T{rt} [style=dashed, label="{esc(short_ent("sub", top, None, 26)[4:])} ×{len(lst)}{(" · age %.0f ms" % (min(ages) / 1e6)) if ages else ""}"];')
            for (wt, rt), n in cbund.items():
                if wt in shown and rt in shown: L.append(f'T{wt} -> T{rt} [style=dotted, color="#e34948", fontcolor="#e34948", label="candidate ×{n}"];')
        else:
            # flat layout (no cluster boxes: dot cannot place 15 large clusters joined by 140 links); the task is the fill colour
            for t in tasks:
                f, s = (FILLS[color[t['id']]], STROKES[color[t['id']]]) if coloured else ('#f4f4f2', '#b5b4ad')
                src_ids = {sr.get('vertex') for sr in t['sources']}
                for v in t['vertices']:
                    if v['id'] not in fold:
                        L.append(f'v{v["id"]} [label="{node_label(v)}{" (src)" if v["id"] in src_ids else ""}", fillcolor="{f}", color="{s}", tooltip="task {t["id"]}"];')
                for (tid, par), vs in folded_groups.items():
                    if tid == t['id']: L.append(f'g{tid}_{par} [label="+{len(vs)} subscribers (sinks)", fillcolor="{f}", color="{s}", style="rounded,filled,dashed", fontsize=7];')
            drawn_group_edges = set()
            # vertices outside the task set (e.g. the rosbag player's publish thread, a stimulus source shared by several topics)
            src_names = collections.defaultdict(set)
            for t in data:
                for sr in t['sources']:
                    if sr.get('vertex') is not None: src_names[sr['vertex']].add(sr['name'])
            extern = {}
            for t in tasks:
                for e in t['edges']:
                    for end in ('u', 'v'):
                        if e[end] not in V and e[end] not in extern:
                            names = src_names.get(e[end], set())
                            if names:
                                nm = next(iter(names)); node = nm.split(' / ')[0].strip('/'); thr = nm.split(' / ')[-1].split(' → ')[0]
                                topics = {n.split(' → ')[-1] for n in names if ' → ' in n}
                                extern[e[end]] = esc(node) + '\\n' + esc(thr) + (('\\n%d topics (stimulus)' % len(topics)) if topics else ' (stimulus)')
                            else: extern[e[end]] = f'vertex {e[end]}'
                            L.append(f'v{e[end]} [label="{extern[e[end]]}", fillcolor="#e8e8e4", color="#8a8a84", style="rounded,filled,dashed"];')
            for t in tasks:
                for e in t['edges']:
                    if e['v'] in fold:
                        g = fold[e['v']]
                        if (e['u'], g) in drawn_group_edges: continue
                        drawn_group_edges.add((e['u'], g)); L.append(f'v{e["u"]} -> g{g[0]}_{g[1]} [color="#9a9990", penwidth=0.8];'); continue
                    L.append(f'v{e["u"]} -> v{e["v"]} [color="{"#8a897f" if e["kind"] == "intra" else "#3a3935"}", penwidth=1.0];')
            # links between tasks at vertex level: the publishing callback of the topic in the writer task -> the reading callback
            pub_in_task = collections.defaultdict(set)
            for t in data:
                for e in t['edges']:
                    if e.get('topic'): pub_in_task[(t['id'], e['topic'])].add(e['u'])
            def task_anchor(wt):   # writer-side anchor when no trigger edge of the writer task carries the topic: its source callback, never a folded sink
                for sr in T[wt]['sources']:
                    if sr.get('vertex') in V and sr['vertex'] not in fold: return sr['vertex']
                for v in T[wt]['vertices']:
                    if v['id'] not in fold: return v['id']
                return T[wt]['vertices'][0]['id']
            seen_pair = set(); n_links = 0
            for sm in links:
                for wt in (sm.get('writer_tasks') or []):
                    if wt not in shown or sm['reader_task'] not in shown or wt == sm['reader_task']: continue
                    wv = sm.get('writer_vertex')
                    if wv in V and VT.get(wv) == wt and wv not in fold: pubs = {wv}        # the extractor names the writing callback
                    else: pubs = {u for u in pub_in_task.get((wt, sm['topic']), set()) if u not in fold} or {task_anchor(wt)}
                    for u in pubs:
                        if u not in V: continue
                        key = (u, sm['reader_vertex'])
                        if key in seen_pair: continue
                        seen_pair.add(key); n_links += 1
                        lab = f'{esc(short_ent("sub", sm["topic"] or "", None, 22)[4:])}{(" · %.0f ms" % (sm["age_p50"] / 1e6)) if sm.get("age_p50") else ""}'
                        tip = esc(sm.get('topic') or '')
                        L.append(f'v{u} -> v{sm["reader_vertex"]} [style=dashed, color="#6b6a63", constraint=true, weight=0, penwidth=0.7, tooltip="{tip}"];')
            for c in cands:
                if VT[c['u']] in shown and VT[c['v']] in shown:
                    L.append(f'v{c["u"]} -> v{c["v"]} [style=dotted, color="#e34948", penwidth=0.9, constraint=true, weight=0];')
        L.append('}')
        dot = f'{a.out}_{kind}.dot'; open(dot, 'w').write('\n'.join(L) + '\n')
        for fmt in ('svg', 'png'):
            r = subprocess.run(['dot', f'-T{fmt}', f'-Gdpi={a.png_dpi}' if fmt == 'png' else '-Gdpi=96', dot, '-o', f'{a.out}_{kind}.{fmt}'], capture_output=True, text=True)
            if r.returncode: print(fmt, r.stderr[:300])
        print(f'{a.out}_{kind}.svg/.png')
    for kind in ('full', 'tasks', 'collapsed'): write(kind)
    print(f"tasks shown {len(tasks)} (multi {len(multi)}), links between tasks {sum(len(v) for v in bund.values())} in {len(bund)} bundles, candidate bundles {len(cbund)}, "
          f"sinks folded {len(fold)} into {len(folded_groups)} boxes")


if __name__ == '__main__':
    main()
